const http=require('node:http'),crypto=require('node:crypto'),fs=require('node:fs');
http.createServer((req,res)=>{if(req.url==='/'){res.setHeader('Content-Type','text/html');res.end(`<html><title>Automation fixture</title><body><h1>Upload/download</h1><input id="file" type="file" aria-label="Upload fixture"><button id="count">Count once</button><p id="status"></p><textarea id="clipboard" aria-label="Clipboard fixture"></textarea><button id="generate">Generate</button><p id="jobstatus"></p><a download="fixture.bin" href="/download">Download</a><script>document.querySelector('#count').onclick=()=>localStorage.setItem('lostreply-count',String(Number(localStorage.getItem('lostreply-count'))+1));document.querySelector('#generate').onclick=()=>{document.querySelector('#jobstatus').textContent='Generating';setTimeout(()=>document.querySelector('#jobstatus').textContent='Ready',12000);};document.querySelector('#file').onchange=async e=>{const file=e.target.files[0];const r=await fetch('/upload',{method:'POST',body:file});document.querySelector('#status').textContent=await r.text();};</script></body></html>`);}else if(req.url==='/upload'){let n=0;const hash=crypto.createHash('sha256');req.on('data',b=>{n+=b.length;hash.update(b)});req.on('end',()=>res.end(JSON.stringify({bytes:n,sha256:hash.digest('hex')})));}else if(req.url==='/download'){res.setHeader('Content-Type','application/octet-stream');res.setHeader('Content-Disposition','attachment; filename="fixture.bin"');res.end(Buffer.alloc(65536,123));}else{res.writeHead(404);res.end();}}).listen(8124,'127.0.0.1');
